/* ===================== BÀI 6 · Nút nhấn và tầng công suất ===================== */
/* ---- công cụ tương tác của bài: chép từ tools/author/nentang/w06.js bởi m02lib.write2 ---- */
/* Bài 6 · Chống dội phím theo thời gian và tầng NPN (AMTS-FND-002-SIM05 / SIM11, bản cho Bài 6).
   NTE6: phần TÍNH (engine), hàm thuần, không đụng DOM; kiểm thử: node tests/nentang/test_m02.js (so với Python độc lập).
   makeNtDebounce: phần VẼ: giản đồ tín hiệu nút (dạng dội GIẢ ĐỊNH, 1 ô = 1 ms), các lần lấy mẫu, đầu ra sau chống dội,
   số lần nhấn đếm được; máy tính tầng NPN đóng cắt phía thấp. Mọi số mặc định là giả định của bài. */
const NTE6={
  /* tín hiệu thô của nút (kéo lên: 1 = nhả, 0 = nhấn), 60 ms, 1 mẫu/ms. GIẢ ĐỊNH: dội khi nhấn 10–14 ms, khi nhả 40–44 ms */
  RAW:(()=>{const r=[];for(let t=0;t<60;t++)r.push(t<10||t>=45?1:t>=16&&t<40?0:[0,1,0,0,1,0][t-10]??[1,0,1,1,0][t-40]);return r})(),
  B:5,D:25,
  /* chống dội "N mẫu giống nhau liên tiếp": lấy mẫu mỗi T ms từ t = 0; trạng thái chỉ đổi khi N mẫu liên tiếp cùng giá trị khác trạng thái.
     Trả {samples:[{t,v}], changes:[{t,s}], out:[mức sau chống dội theo từng ms], presses: số lần chuyển 1 → 0} */
  debounce(raw,T,N){T=Math.max(1,Math.floor(T));N=Math.max(1,Math.floor(N));
    let state=raw.length?raw[0]:1,cand=state,cnt=N,presses=0;const samples=[],changes=[],out=[];
    for(let t=0;t<raw.length;t++){
      if(t%T===0){const v=raw[t];samples.push({t,v});if(v===cand)cnt++;else{cand=v;cnt=1}
        if(cnt>=N&&cand!==state){state=cand;changes.push({t,s:state});if(state===0)presses++}}
      out.push(state)}
    return{samples,changes,out,presses}},
  /* hai điều kiện chọn thông số (giải thích trong bài): (N−1)·T > B (không đổi giả trong lúc dội), N·T ≤ D (không mất lần nhấn) */
  rules(T,N,B,D){return{hold:(N-1)*T,safe:(N-1)*T>B,win:N*T,keep:N*T<=D}},
  /* tầng NPN đóng cắt phía thấp. c = {vl: nguồn tải, rl: điện trở cuộn (Ω), vce: VCE(sat), beta: hệ số ép, vd: điện áp lái, vbe, ipin: giới hạn chân (mA)}.
     Trả ic, ib (mA), rbMax (Ω), rb (E12 ≤ rbMax), ibReal, p (mW) */
  npn(c){if([c.vl,c.rl,c.vce,c.beta,c.vd,c.vbe].some(x=>!isFinite(x)))return{ok:false,err:"Thiếu hoặc sai một thông số."};
    if(!(c.rl>0&&c.beta>0))return{ok:false,err:"Điện trở cuộn và hệ số β phải lớn hơn 0."};
    const ic=(c.vl-c.vce)/c.rl*1000;if(!(ic>0))return{ok:false,err:"Nguồn tải phải lớn hơn VCE(sat)."};
    const ib=ic/c.beta,head=c.vd-c.vbe;if(!(head>0))return{ok:false,err:"Điện áp lái phải lớn hơn VBE: transistor không dẫn."};
    const rbMax=head/(ib/1000),rb=nte6E12Down(rbMax),ibReal=head/rb*1000;
    return{ok:true,ic,ib,rbMax,rb,ibReal,p:c.vce*ic,over:isFinite(c.ipin)&&ibReal>c.ipin}}
};
/* E12 làm tròn XUỐNG (điện trở base: chọn nhỏ hơn để dòng base không thiếu); viết riêng, không phụ thuộc engine của Bài 5 */
function nte6E12Down(r){if(!(r>0)||!isFinite(r))return NaN;let best=NaN;
  for(let k=-1;k<=7;k++)for(const m of[10,12,15,18,22,27,33,39,47,56,68,82]){const v=Number((m*Math.pow(10,k)).toPrecision(12));if(v<=r*(1+1e-9)&&!(v<=best))best=v}
  return best}
function makeNtDebounce(el,cfg){
  cfg=cfg||{};const P="ntd-"+(cfg.id||"x");
  const f=(x,d)=>{let s=x.toFixed(d);if(s.includes("."))s=s.replace(/0+$/,"").replace(/\.$/,"");return s.replace(".",",")};
  el.classList.add("nt6-db");
  const opt=(a,v)=>a.map(x=>`<option value="${x}"${x===v?" selected":""}>${x}</option>`).join("");
  el.innerHTML=`<fieldset class="nt5-box"><legend>Chống dội phím: lấy mẫu N lần giống nhau</legend>
    <div class="nt6-ctl"><label>Chu kỳ lấy mẫu T <select id="${P}-t">${opt([1,2,4,5,10,20],cfg.T||1)}</select> ms</label><label>Số mẫu giống nhau N <select id="${P}-n">${opt([1,2,3,4,5],cfg.N||1)}</select></label></div>
    <div id="${P}-w"></div>
    <p class="nt6-sum" id="${P}-sum" role="status" aria-live="polite"></p></fieldset>
   <fieldset class="nt5-box"><legend>Tầng NPN đóng cắt cuộn rơ-le</legend>
    <div class="nt5-grid">${[["vl","Nguồn tải","12","V"],["rl","Điện trở cuộn","400","Ω"],["vce","V<sub>CE(sat)</sub>","0,2","V"],["beta","β ép (I<sub>C</sub>/I<sub>B</sub>)","10",""],["vd","Điện áp lái base","4,5","V"],["vbe","V<sub>BE</sub>","0,7","V"],["ipin","Giới hạn chân","10","mA"]]
      .map(([k,l,v,u])=>`<label class="nt5-f"><span>${l}</span><span class="nt5-iu"><input id="${P}-${k}" type="text" inputmode="decimal" autocomplete="off" value="${v}"><i>${u}</i></span></label>`).join("")}</div>
    <p class="nt-err" id="${P}-err" role="status" aria-live="polite"></p>
    <dl class="nt-out" aria-live="polite"><dt>I<sub>C</sub></dt><dd id="${P}-ic"></dd><dt>I<sub>B</sub> cần</dt><dd id="${P}-ib"></dd><dt>R<sub>B</sub> lớn nhất</dt><dd id="${P}-rbm"></dd><dt>Chọn E12 (≤)</dt><dd id="${P}-rb"></dd><dt>I<sub>B</sub> thực</dt><dd id="${P}-ibr"></dd><dt>Công suất transistor</dt><dd id="${P}-p"></dd></dl></fieldset>
   <p class="mt-cap">Dạng dội, thời gian dội 5 ms và thời gian nhấn ổn định 25 ms là giả định; công tắc thật phải đo bằng máy hiện sóng hoặc tra datasheet. Tầng NPN là mô hình bão hòa đơn giản (V<sub>CE(sat)</sub>, V<sub>BE</sub> không đổi).</p>`;
  const $=s=>el.querySelector("#"+P+"-"+s);
  function draw(){const T=+$("t").value,N=+$("n").value,r=NTE6.debounce(NTE6.RAW,T,N),R=NTE6.rules(T,N,NTE6.B,NTE6.D);
    const st=new Set(r.samples.map(s=>s.t)),cell=(v,c)=>`<i class="${v?"h":""}${c?" "+c:""}"></i>`,row=(a,cls)=>a.map((v,t)=>cell(v,(t>0&&a[t-1]!==v?"e ":"")+(cls?cls(t):""))).join("");
    $("w").innerHTML=`<div class="nt2-wave" role="img" aria-label="Giản đồ 60 ms: tín hiệu thô, các lần lấy mẫu, đầu ra sau chống dội"><b>Thô</b><div style="--n:60">${row(NTE6.RAW,t=>st.has(t)?"s":"")}</div><b>Sau lọc</b><div style="--n:60">${row(r.out,t=>r.changes.some(c=>c.t===t)?"c":"")}</div><b></b><div class="nt2-ax" style="--n:60">${Array.from({length:60},(_,t)=>`<i>${t%10===0?t:""}</i>`).join("")}</div></div>`;
    $("sum").innerHTML=`Lấy mẫu ${r.samples.length} lần (ô xanh). Đổi trạng thái tại ${r.changes.length?r.changes.map(c=>`${c.t} ms → ${c.s}`).join(", "):"không lần nào"}. <b>Đếm được ${r.presses} lần nhấn</b> (thực tế: 1). `+
      `(N − 1)·T = ${R.hold} ms ${R.safe?">":"≤"} ${NTE6.B} ms thời gian dội: ${R.safe?"không đổi giả":"có thể đổi giả trong lúc dội"}; N·T = ${R.win} ms ${R.keep?"≤":">"} ${NTE6.D} ms nhấn ổn định: ${R.keep?"không mất lần nhấn":"có thể mất lần nhấn"}.`}
  function npn(){const g=k=>{const s=$(k).value.trim().replace(",",".");return/^[-+]?(\d+\.?\d*|\.\d+)$/.test(s)?+s:NaN};
    const r=NTE6.npn({vl:g("vl"),rl:g("rl"),vce:g("vce"),beta:g("beta"),vd:g("vd"),vbe:g("vbe"),ipin:g("ipin")});
    ["ic","ib","rbm","rb","ibr","p"].forEach(k=>$(k).textContent="");
    if(!r.ok){$("err").textContent=r.err;return}
    $("err").textContent=r.over?`I_B thực ${f(r.ibReal,2)} mA vượt giới hạn chân: chọn transistor β lớn hơn, MOSFET hoặc IC đệm.`:"";
    $("ic").textContent=f(r.ic,2)+" mA";$("ib").textContent=f(r.ib,3)+" mA";$("rbm").textContent=f(r.rbMax,1)+" Ω";
    $("rb").textContent=r.rb>=1000?f(r.rb/1000,2)+" kΩ":f(r.rb,1)+" Ω";$("ibr").textContent=f(r.ibReal,3)+" mA";$("p").textContent=f(r.p,2)+" mW"}
  $("t").onchange=$("n").onchange=draw;
  el.querySelectorAll("input").forEach(x=>x.addEventListener("input",npn));
  draw();npn()}
